### 4.2 Design Compiler Integration Point

**New Module**: `src/compiler/design-integration.ts`
```typescript
export class DesignIntegration {
  private designCompiler: DesignCompiler;

  constructor() {
    this.designCompiler = new DesignCompiler();
  }

  /**
   * Process design blocks from parsed module
   */
  compileDesignBlocks(
    designBlocks: DesignBlockDeclaration[]
  ): {
    css: string;
    javascript: string;
    ast: DesignBlockDeclaration[];
  } {
    // Convert AST blocks to design compiler format
    const content = this._toDesignCompilerFormat(designBlocks);

    // Compile
    const result = this.designCompiler.compileDesignBlocks(content);

    return {
      css: result.css,
      javascript: result.javascript,
      ast: designBlocks
    };
  }

  private _toDesignCompilerFormat(blocks: DesignBlockDeclaration[]): string {
    return blocks
      .map(b => `@${b.engine}${b.name ? ' ' + b.name : ''} { ${this._formatProperties(b.properties)} }`)
      .join('\n');
  }
}
```

